import { useState } from "react";
import axios from "axios";

export default function Login({ goSignup }) {
  const [data, setData] = useState({});

  const login = async () => {
    const res = await axios.post("http://localhost:5000/login", data);
    alert(res.data.message);
  };

  const sendOtp = async () => {
    const res = await axios.post("http://localhost:5000/send-otp", {
      phone: data.phone
    });
    alert(res.data.message);
  };

  return (
    <div>
      <h2>Login</h2>

      <input placeholder="Email" onChange={e => setData({...data, email: e.target.value})} />
      <input type="password" placeholder="Password" onChange={e => setData({...data, password: e.target.value})} />

      <button onClick={login}>Login</button>

      <hr />

      <input placeholder="Phone" onChange={e => setData({...data, phone: e.target.value})} />
      <button onClick={sendOtp}>Login with OTP</button>

      <p onClick={goSignup}>Create Account</p>
    </div>
  );
}
